#include<stdio.h>
#include<queue>
#include<ctype.h>
#include<vector>
#include<string.h>
using namespace std;

#define inf 12345678

struct node{
    int i;
    int j;
    int no;
};

struct cap{
    int no[1000];
    int ind;
    int fl;
};

cap caps[100][100];
vector<int>v[1000];
int n,t;
int left[1000],right[1000],col[1000];
char grid[1000][1000],grid1[1000][1000];
int d[1000][1000],d1[1000][1000];
queue<node>q;

void bfs(node s);
void bfst(node s);
int match(int n);
bool dfs(int s);

int main(){

    int i,j,k,l;
    node temp,temp1;

    //freopen("in.txt","r",stdin);

    scanf("%d %d",&n,&t);

    for(i=0;i<=n;i++){
        for(j=0;j<=n;j++){
            d[i][j]=inf;
        }
    }


    for(i=0;i<n;i++){
        scanf("%s",grid[i]);
    }

    for(i=0;i<n;i++){
        scanf("%s",grid1[i]);
    }
    for(i=0;i<n;i++){
        for(j=0;j<n;j++){
            if(grid[i][j]=='Z'){
                temp.i=i;
                temp.j=j;
                bfs(temp);              
            }
        }
    }
    int mark=1;

    for(i=0;i<n;i++){
        for(j=0;j<n;j++){
            if(isdigit(grid1[i][j])){
                k=grid1[i][j]-'0';
                if(k>0)caps[i][j].fl=1;
                caps[i][j].ind=k;
                for(l=1;l<=k;l++){
                    caps[i][j].no[l]=mark++;
                }
            }
        }
    }
    mark=1;



    for(i=0;i<n;i++){
        for(j=0;j<n;j++){
            if(isdigit(grid[i][j])){
                k=grid[i][j]-'0';
                for(l=1;l<=k;l++){
                    temp.i=i; temp.j=j; temp.no=mark++;
                    bfst(temp);
                }
            }
        }
    }

//  for(i=1;i<mark;i++){
//      for(j=0;j<v[i].size();j++){
//          printf("%d ",v[i][j]);
//      }
//      printf("\n");
//  }

    printf("%d\n",match(mark-1));



    return 0;
}

bool dfs(int s){

    if(col[s]) return 0;
    int i,j,k,l;
    col[s]=1;

    for(i=0;i<v[s].size();i++){
        k=v[s][i];
        if(left[k]==-1){
            left[k]=s;
            right[s]=i;
            return true;
        }
        else if(dfs(left[k])){
            left[k]=s;
            right[s]=i;
            return true;
        }
    }

    return false;

}


int match(int n){

    memset(left,-1,sizeof(left));
    memset(right,-1,sizeof(right));
    int i,j,k,l,done;

    do{

        done=1;
        memset(col,0,sizeof(col));

        for(i=1;i<=n;i++){
            if(right[i]==-1&&dfs(i)) done=0;
        }



    }while(!done);

    k=0;

    for(i=1;i<=n;i++){
        if(right[i]!=-1) k++;

    }

    return k;

}

